    spec_ref: "@test-trait-feature"
    tags: []
    depends_on: []
    blocked_by: []
    notes: []
    todos: []
    created_at: "2026-01-20T00:00:00Z"
`;

    await fs.writeFile(
      path.join(tempDir, 'project.tasks.yaml'),
      tasksFile
    );

    expect(() => {
      kspec('item trait add @test-task @json-output', tempDir);
    }).toThrow(/task/i);
