    await fs.mkdir(path.join(tempDir, 'modules'), { recursive: true });
    const specModule = `_ulid: 01KFCVXQAABBCCDDEEFFGGHHXX
slugs:
  - test-spec
title: Test Spec
type: module
traits:
  - "@json-output"
`;
    await fs.writeFile(
      path.join(tempDir, 'modules/test.yaml'),
      specModule
    );

