  });

  it('should return full trait data in JSON mode', () => {
    const result = kspecJson<{
      trait: {
        ulid: string;
        slug: string;
        title: string;
        description: string;
        acceptanceCriteria: Array<{ id: string; given: string; when: string; then: string }>;
      };
